window.RP_SESSION={"id":"S-88a9c7986ed4","messages":[{"id":"RP-0270603","time":"2026-09-12T16:49:00+09:00","room":"RP","name":"진 프테라리온","profile":"헥터","identity":"reviewed","type":"dialogue","body":"그녀는 잠을 청했다.\n하지만 잠은 오지 않았다.\n왜일까..\n잡생각이 너무 많은 것일까?\n그녀는 생각을 멈추고선 양을 세어보기로 하였다.\n한마리..두마리..세마리째 갑자기 양이 진의 눈을 쳐다보았다.\n그 양의 털은 다른 양들과는 달리 매끄럽고 기름기가 흘렀다.\n그 양의 눈은 그녀의 눈을 그윽하게 바라보며...\n\n\" 으악..! \"\n그녀는 자리에서 벌떡 일어나다 침대에 머리를 찍었다.\n\n잠깐동안 잠든사이에 양을 세는 꿈을.. 그것도 그런 기이하고 소름끼치는 꿈을 꾼것이었다.\n\n한참동안 부딪친 머리를 부여잡은채 아파하던 그녀는 그렇게 뜬눈으로 밤을 지새우는 수밖에 없었다...","characters":["P-5d0982a87f77"]},{"id":"RP-0270604","time":"2026-09-12T16:50:00+09:00","room":"RP","name":"진 프테라리온","profile":"헥터","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5d0982a87f77"]},{"id":"RP-0270605","time":"2026-09-12T16:50:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
